"\"\"\"Standalone fusion head MLP for combining modality embeddings.\"\"\"\nfrom __future__ import annotations\n\nfrom typing import List, Optional\n\nimport torch\nimport torch.nn as nn\n\n\nclass FusionHead(nn.Module):\n    \"\"\"MLP head that fuses concatenated modality embeddings.\n\n    Args:\n        input_dim: Total concatenated embedding dimension.\n        hidden_dims: Hidden layer sizes.\n        num_classes: Output classes.\n        dropout: Dropout probability.\n    \"\"\"\n\n    def __init__(\n        self,\n        input_dim: int,\n        hidden_dims: List[int],\n        num_classes: int,\n        dropout: float = 0.3,\n    ):\n        super().__init__()\n        layers = []\n        in_dim = input_dim\n        for h in hidden_dims:\n            layers += [\n                nn.Linear(in_dim, h),\n                nn.LayerNorm(h),\n                nn.GELU(),\n                nn.Dropout(dropout),\n            ]\n            in_dim = h\n        layers.append(nn.Linear(in_dim, num_classes))\n        self.net = nn.Sequential(*layers)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        return self.net(x)\n"